    if msg:
        print(msg)
    print(json.dumps({"score": max(0.0, min(1.0, score))}))
    sys.exit(0)


def norm(p):
    p = p.strip().replace("\\", "/")
    while p.startswith("./"):
        p = p[2:]
    if p.startswith(("a/", "b/")):
